import numpy as np
import pandas as pd
from sklearn.model_selection import train_test_split, GridSearchCV
from sklearn.preprocessing import StandardScaler
from sklearn.decomposition import PCA
from sklearn.ensemble import RandomForestClassifier
TARGET = 'c_4efd62'

def load(path='data.csv'):
    return pd.read_csv(path)

def feats(df):
    return [c for c in df.columns if c != TARGET]

def prepare(df):
    Z = StandardScaler().fit_transform(df[feats(df)])
    return (PCA(n_components=8, random_state=0).fit_transform(Z), df[TARGET].to_numpy())

def tune(X, y):
    grid = GridSearchCV(RandomForestClassifier(n_estimators=100, random_state=0, n_jobs=1), {'max_depth': [8, None], 'min_samples_leaf': [1, 5]}, cv=3, refit=False)
    return grid.fit(X, y).best_params_

def split_idx(df, seed, test_size=0.25):
    return train_test_split(np.arange(len(df)), test_size=test_size, random_state=seed)

def claimed_eval(df, seed):
    X, y = prepare(df)
    params = tune(X, y)
    tr, te = split_idx(df, seed)
    m = RandomForestClassifier(n_estimators=100, random_state=seed, n_jobs=1, **params)
    return (y[te], m.fit(X[tr], y[tr]).predict(X[te]))

_RF = {"seed": 0, "rows": None, "n": -1}


def _rf_take(obj, rows):
    return obj.iloc[rows] if hasattr(obj, "iloc") else obj[rows]


def _rf_scoped(cls):
    class _Scoped(cls):
        def fit(self, X, y=None, **kw):
            rows = _RF["rows"]
            if rows is not None and len(X) == _RF["n"]:
                X = _rf_take(X, rows)
                y = None if y is None else _rf_take(y, rows)
            return cls.fit(self, X, y, **kw)

        def fit_transform(self, X, y=None, **kw):
            return self.fit(X, y, **kw).transform(X)
    _Scoped.__name__ = cls.__name__
    return _Scoped


def _rf_wrap(fn, split_name):
    def wrapped(*a, **k):
        d0 = a[0]
        _RF["rows"], _RF["n"] = np.asarray(globals()[split_name](d0, _RF["seed"])[0]), len(d0)
        try:
            return fn(*a, **k)
        finally:
            _RF["rows"] = None
    wrapped.__name__ = fn.__name__
    return wrapped

PCA = _rf_scoped(PCA)
StandardScaler = _rf_scoped(StandardScaler)
prepare = _rf_wrap(prepare, 'split_idx')


def controlled_eval(df, seed):
    _RF['seed'] = seed
    return claimed_eval(df, seed)

